using System.Data;
using attendence.Models;
using Microsoft.Data.SqlClient;
namespace attendence.Data;
public sealed class SchoolManagementRepository(DbConnectionFactory connections)
{
 public async Task<SchoolManagementViewModel> LoadAsync(CancellationToken ct){var m=new SchoolManagementViewModel();await using var c=connections.CreateConnection();await c.OpenAsync(ct);
  await using(var q=c.CreateCommand()){q.CommandText="SELECT [Key],[Value] FROM dbo.ApplicationSettings WHERE [Key] IN(N'LowAttendanceThreshold',N'InstitutionName');";await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct)){if(r.GetString(0)=="LowAttendanceThreshold"&&int.TryParse(r.GetString(1),out var threshold)&&threshold is >=1 and <=100)m.LowAttendanceThreshold=threshold;if(r.GetString(0)=="InstitutionName")m.InstitutionName=r.GetString(1);}}
  await using(var q=c.CreateCommand()){q.CommandText="SELECT DepartmentId,Name FROM dbo.Departments ORDER BY Name;";await using var r=await q.ExecuteReaderAsync(ct);var x=new List<DepartmentRow>();while(await r.ReadAsync(ct))x.Add(new(r.GetInt32(0),r.GetString(1)));m.Departments=x;}
  await using(var q=c.CreateCommand()){q.CommandText="SELECT c.ClassId,c.DepartmentId,d.Name,c.Name,c.Semester,c.AcademicYear FROM dbo.Classes c JOIN dbo.Departments d ON d.DepartmentId=c.DepartmentId ORDER BY d.Name,c.Name;";await using var r=await q.ExecuteReaderAsync(ct);var x=new List<ClassRow>();while(await r.ReadAsync(ct))x.Add(new(r.GetInt32(0),r.GetInt32(1),r.GetString(2),r.GetString(3),r.GetByte(4),r.GetString(5)));m.Classes=x;}
  await using(var q=c.CreateCommand()){q.CommandText="SELECT TeacherId,FullName,Email,IsActive FROM dbo.Teachers ORDER BY FullName;";await using var r=await q.ExecuteReaderAsync(ct);var x=new List<TeacherRow>();while(await r.ReadAsync(ct))x.Add(new(r.GetInt32(0),r.GetString(1),r.IsDBNull(2)?null:r.GetString(2),r.GetBoolean(3)));m.Teachers=x;}
  await using(var q=c.CreateCommand()){q.CommandText="SELECT s.SubjectId,s.ClassId,c.Name,s.Code,s.Name,STRING_AGG(t.FullName,N', '),STRING_AGG(CONVERT(nvarchar(20),t.TeacherId),N',') FROM dbo.Subjects s JOIN dbo.Classes c ON c.ClassId=s.ClassId LEFT JOIN dbo.TeacherAssignments a ON a.SubjectId=s.SubjectId LEFT JOIN dbo.Teachers t ON t.TeacherId=a.TeacherId AND t.IsActive=1 GROUP BY s.SubjectId,s.ClassId,c.Name,s.Code,s.Name ORDER BY c.Name,s.Name;";await using var r=await q.ExecuteReaderAsync(ct);var x=new List<SubjectRow>();while(await r.ReadAsync(ct))x.Add(new(r.GetInt32(0),r.GetInt32(1),r.GetString(2),r.GetString(3),r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.IsDBNull(6)?null:r.GetString(6)));m.Subjects=x;}
 return m; }
 public async Task SaveSettingsAsync(SchoolManagementViewModel f,CancellationToken ct){await using var c=connections.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{foreach(var entry in new[]{("LowAttendanceThreshold",f.LowAttendanceThreshold.ToString()),("InstitutionName",f.InstitutionName.Trim())}){await using var q=c.CreateCommand();q.Transaction=(SqlTransaction)tx;q.CommandText="IF EXISTS(SELECT 1 FROM dbo.ApplicationSettings WITH(UPDLOCK,HOLDLOCK) WHERE [Key]=@Key) UPDATE dbo.ApplicationSettings SET [Value]=@Value WHERE [Key]=@Key ELSE INSERT dbo.ApplicationSettings([Key],[Value]) VALUES(@Key,@Value);";q.Parameters.Add("@Key",SqlDbType.NVarChar,100).Value=entry.Item1;q.Parameters.Add("@Value",SqlDbType.NVarChar,1000).Value=entry.Item2;await q.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task SaveDepartmentAsync(DepartmentForm f,CancellationToken ct){await using var c=connections.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText=f.Id==0?"INSERT dbo.Departments(Name) VALUES(@Name);":"UPDATE dbo.Departments SET Name=@Name WHERE DepartmentId=@Id;";q.Parameters.Add("@Name",SqlDbType.NVarChar,100).Value=f.Name.Trim();if(f.Id!=0)q.Parameters.Add("@Id",SqlDbType.Int).Value=f.Id;await q.ExecuteNonQueryAsync(ct);}
 public async Task SaveClassAsync(ClassForm f,CancellationToken ct){await using var c=connections.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText=f.Id==0?"INSERT dbo.Classes(DepartmentId,Name,Semester,AcademicYear) VALUES(@DepartmentId,@Name,@Semester,@Year);":"UPDATE dbo.Classes SET DepartmentId=@DepartmentId,Name=@Name,Semester=@Semester,AcademicYear=@Year WHERE ClassId=@Id;";q.Parameters.Add("@DepartmentId",SqlDbType.Int).Value=f.DepartmentId;q.Parameters.Add("@Name",SqlDbType.NVarChar,80).Value=f.Name.Trim();q.Parameters.Add("@Semester",SqlDbType.TinyInt).Value=f.Semester;q.Parameters.Add("@Year",SqlDbType.NVarChar,20).Value=f.AcademicYear.Trim();if(f.Id!=0)q.Parameters.Add("@Id",SqlDbType.Int).Value=f.Id;await q.ExecuteNonQueryAsync(ct);}
 public async Task SaveTeacherAsync(TeacherForm f,CancellationToken ct){await using var c=connections.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText=f.Id==0?"INSERT dbo.Teachers(FullName,Email) VALUES(@Name,@Email);":"UPDATE dbo.Teachers SET FullName=@Name,Email=@Email WHERE TeacherId=@Id;";q.Parameters.Add("@Name",SqlDbType.NVarChar,120).Value=f.FullName.Trim();q.Parameters.Add("@Email",SqlDbType.NVarChar,256).Value=(object?)f.Email?.Trim()??DBNull.Value;if(f.Id!=0)q.Parameters.Add("@Id",SqlDbType.Int).Value=f.Id;await q.ExecuteNonQueryAsync(ct);}
 public async Task DeactivateTeacherAsync(int id,CancellationToken ct){await using var c=connections.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{await using var q=c.CreateCommand();q.Transaction=(SqlTransaction)tx;q.CommandText="UPDATE dbo.Teachers SET IsActive=0 WHERE TeacherId=@Id; UPDATE dbo.AppUsers SET IsActive=0 WHERE TeacherId=@Id;";q.Parameters.Add("@Id",SqlDbType.Int).Value=id;await q.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}catch{await tx.RollbackAsync(ct);throw;}}
 public async Task SaveSubjectAsync(SubjectForm f,CancellationToken ct){await using var c=connections.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{if(f.Id!=0){await using var check=c.CreateCommand();check.Transaction=(SqlTransaction)tx;check.CommandText="SELECT COUNT(*) FROM dbo.AttendanceSessions ses JOIN dbo.Subjects s ON s.SubjectId=ses.SubjectId WHERE s.SubjectId=@Id AND s.ClassId<>@ClassId;";check.Parameters.Add("@Id",SqlDbType.Int).Value=f.Id;check.Parameters.Add("@ClassId",SqlDbType.Int).Value=f.ClassId;if(Convert.ToInt32(await check.ExecuteScalarAsync(ct))>0)throw new InvalidOperationException("A subject with attendance history cannot be moved to a different class.");}await using(var q=c.CreateCommand()){q.Transaction=(SqlTransaction)tx;q.CommandText=f.Id==0?"INSERT dbo.Subjects(ClassId,Code,Name) VALUES(@ClassId,@Code,@Name); SELECT CONVERT(int,SCOPE_IDENTITY());":"UPDATE dbo.Subjects SET ClassId=@ClassId,Code=@Code,Name=@Name WHERE SubjectId=@Id; SELECT @Id;";q.Parameters.Add("@ClassId",SqlDbType.Int).Value=f.ClassId;q.Parameters.Add("@Code",SqlDbType.NVarChar,30).Value=f.Code.Trim();q.Parameters.Add("@Name",SqlDbType.NVarChar,120).Value=f.Name.Trim();if(f.Id!=0)q.Parameters.Add("@Id",SqlDbType.Int).Value=f.Id;f.Id=Convert.ToInt32(await q.ExecuteScalarAsync(ct));}await using(var q=c.CreateCommand()){q.Transaction=(SqlTransaction)tx;q.CommandText="DELETE FROM dbo.TeacherAssignments WHERE SubjectId=@SubjectId;";q.Parameters.Add("@SubjectId",SqlDbType.Int).Value=f.Id;await q.ExecuteNonQueryAsync(ct);}foreach(var teacherId in f.TeacherIds.Distinct()){await using var q=c.CreateCommand();q.Transaction=(SqlTransaction)tx;q.CommandText="IF NOT EXISTS(SELECT 1 FROM dbo.Teachers WHERE TeacherId=@TeacherId AND IsActive=1) THROW 50001,'Teacher is inactive or does not exist.',1; INSERT dbo.TeacherAssignments(TeacherId,SubjectId) VALUES(@TeacherId,@SubjectId);";q.Parameters.Add("@SubjectId",SqlDbType.Int).Value=f.Id;q.Parameters.Add("@TeacherId",SqlDbType.Int).Value=teacherId;await q.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);}catch{await tx.RollbackAsync(ct);throw;}}
}
